const fire = (e: CatEvent) => {
  driver.current.events.push(e);
  onEvent?.(e);
};

useFrame((_, rawDt) => {
  const dt = Math.min(rawDt, 0.05);
  S.t += dt;
  const t = S.t;
  const d = driver.current;
  const o = R.current;
  if (!o.root) return;

  /* ---- events ---- */
  if (d.events.length) {
    for (const e of d.events) {
      const f = EVENT_FLASH[e];
      if (f) S.flash = { name: f[0], until: t + f[1] };
      const em = EVENT_EMOTE[e];
      if (em) S.emote = { name: em[0], until: t + em[1] };
      if (S.asleep && e !== "wakeUp") {
        S.asleep = false;
        S.fidget = null;
        S.flash = { name: "shocked", until: t + 0.6 };
        S.emote = { name: "exclaim", until: t + 0.6 };
      }
      S.fidget = null;
      S.idleFor = 0;
      switch (e) {
        case "land":
          S.springs.stretch.impulse(-7);
          S.earL.impulse(-9);
          S.earR.impulse(-9);
          S.earTipL.impulse(-6);
          S.earTipR.impulse(-6);
          S.head.impulse(0, 5);
          S.jiggle.impulse(6);
          S.cheek.impulse(5);
          S.tail.impulse(3);
          break;
        case "jump":
          S.springs.stretch.impulse(4.5);
          S.head.impulse(0, -3);
          S.tail.impulse(-3);
          break;
        case "superJump":
        case "rocketOn":
          S.springs.stretch.impulse(10);
          S.earL.impulse(-14);
          S.earR.impulse(-14);
          S.head.impulse(0, -6);
          S.tail.impulse(-6);
          S.jiggle.impulse(-3);
          break;
        case "spring":
          S.springs.stretch.impulse(8);
          S.head.impulse(0, -5);
          S.roll = 0.0001;
          break;
        case "collect":
        case "yum":
          S.springs.headTilt.impulse(3);
          S.springs.stretch.impulse(2.5);
          S.cheek.impulse(3);
          break;
        case "star":
        case "record":
        case "milestone":
          S.springs.stretch.impulse(4);
          S.earL.impulse(10);
          S.earR.impulse(10);
          S.sparkle = 1;
          S.tail.impulse(5);
          break;
        case "hurt":
          S.springs.stretch.impulse(-5);
          S.tailRoot.impulse(6);
          S.head.impulse(4, 2);
          S.jiggle.impulse(4);
          break;
        case "hugged":
        case "pet":
          S.springs.stretch.impulse(-3);
          S.earL.impulse(-6);
          S.earR.impulse(-6);
          S.cheek.impulse(3);
          S.tail.impulse(4);
          break;
        case "bump":
        case "wrap":
          S.springs.headTilt.impulse(-4);
          S.earL.impulse(8);
          S.head.impulse(-6, 0);
          break;
        case "cheer":
        case "perfect":
          S.springs.stretch.impulse(6);
          S.tail.impulse(6);
          break;
        case "slip":
          S.springs.lean.impulse(6);
          S.armLag.impulse(8);
          S.head.impulse(-5, 2);
          break;
        case "stun":
          S.head.impulse(rand(-8, 8), 4);
          S.earL.impulse(-12);
          S.earR.impulse(12);
          S.jiggle.impulse(5);
          break;
        case "shieldOn":
          S.shieldPulse = 1;
          S.springs.stretch.impulse(3);
          break;
        case "shieldPop":
        case "balloonPop":
          S.springs.stretch.impulse(-4);
          S.earL.impulse(-10);
          S.earR.impulse(-10);
          S.head.impulse(0, 3);
          break;
        case "balloonOn":
          S.springs.stretch.impulse(3);
          S.balloon.impulse(0, 6);
          break;
        case "magnet":
          S.earL.impulse(9);
          S.earR.impulse(9);
          break;
        case "poke":
          S.head.impulse(0, 6);
          S.earL.impulse(-12);
          S.earR.impulse(-12);
          S.springs.stretch.impulse(-3);
          break;
        case "pokeBelly":
          S.jiggle.impulse(10);
          S.springs.stretch.impulse(-4);
          S.cheek.impulse(6);
          break;
        case "pokeTail":
          S.tail.impulse(18, 0.9);
          S.tailRoot.impulse(10);
          S.head.impulse(6, 0);
          S.earL.impulse(-12);
          S.earR.impulse(-12);
          break;
        case "nearMiss":
          S.head.impulse(0, -3);
          S.whiskerL.impulse(6);
          S.whiskerR.impulse(6);
          break;
        case "startle":
          S.springs.stretch.impulse(8);
          S.earL.impulse(14);
          S.earR.impulse(14);
          S.tail.impulse(-12, 0.9);
          S.whiskerL.impulse(10);
          S.whiskerR.impulse(10);
          break;
        case "wakeUp":
          S.asleep = false;
          S.springs.stretch.impulse(3);
          S.earL.impulse(8);
          S.earR.impulse(8);
          break;
      }
    }
    d.events.length = 0;
  }

